    }

    private final List<Member> members = new ArrayList<>();

    public void join(String name, LocalDate when) {
        members.add(new Member(name, when));
    }

    public boolean markPaid(String name) {
        for (Member m : members) {
            if (m.name == name) { m.paid = true; return true; }
        }
        return false;
    }

    public List<String> unpaidSince(LocalDate cutoff) {
        List<String> out = new ArrayList<>();
        for (Member m : members) {
            if (!m.paid && m.joined.isAfter(cutoff)) out.add(m.name);
        }
        return out;
    }

    public int size() { return members.size(); }
}
